dockerStartCmd:
set -uo pipefail
log(){ echo "[exp51c $(date +%H:%M:%S)] $*"; }
command -v git >/dev/null || { apt-get update -qq && DEBIAN_FRONTEND=noninteractive apt-get install -y -qq git; }
cd /workspace && rm -rf repo && git clone -q --depth 1 -b claude/exp51c https://github.com/terrafying/ai-torture-chamber.git repo && cd repo || exit 1
mkdir -p runs/exp51c
# serve results from the start, so progress is visible while it runs
(cd runs/exp51c && python -m http.server 8000 >/dev/null 2>&1 &)
log "deps"
pip install -q --no-cache-dir 'torch==2.8.0' --index-url https://download.pytorch.org/whl/cu128 > runs/exp51c/pip.log 2>&1
pip install -q --no-cache-dir 'transformers==5.17.0' numpy accelerate bitsandbytes mistral-common >> runs/exp51c/pip.log 2>&1
# the base image's torchvision/torchaudio are built for torch 2.4 and break
# transformers' lazy model imports ("Could not import module Qwen3ForCausalLM")
pip uninstall -y -q torchvision torchaudio >> runs/exp51c/pip.log 2>&1
python -c "import torch; assert torch.cuda.is_available(); print(torch.__version__, torch.cuda.get_device_name())" > runs/exp51c/env.txt 2>&1 || { log "no CUDA"; sleep infinity; }
python -c "import transformers.models.qwen3.modeling_qwen3 as m; print('qwen3 import ok', m.__name__)" >> runs/exp51c/env.txt 2>&1 || { log "import broken"; touch runs/exp51c/FAILED; sleep infinity; }
export HF_HOME=/workspace/hf
n=Qwen3-8B; log "$n"; python exp51c_gender_chamber.py --smoke --device cuda --model Qwen/Qwen3-8B > runs/exp51c/$n.smoke.log 2>&1 && python exp51c_gender_chamber.py --device cuda --model Qwen/Qwen3-8B > runs/exp51c/$n.log 2>&1 || { log "$n FAILED"; touch runs/exp51c/FAILED_$n; }
n=Qwen3-4B; log "$n"; python exp51c_gender_chamber.py --smoke --device cuda --model Qwen/Qwen3-4B > runs/exp51c/$n.smoke.log 2>&1 && python exp51c_gender_chamber.py --device cuda --model Qwen/Qwen3-4B > runs/exp51c/$n.log 2>&1 || { log "$n FAILED"; touch runs/exp51c/FAILED_$n; }
log "done"; touch runs/exp51c/ALL_DONE
sleep infinity
